input.command:
cat > /tmp/w/run.sh <<'SH'
#!/bin/bash
# reads templates one per line from stdin (with \n literal escapes intact), prints | tmpl | output |
while IFS= read -r line; do
  [ -z "$line" ] && continue
  out=$(/workspace/executable -i "$line" 2>/tmp/w/e); code=$?
  if [ $code -ne 0 ]; then
    err=$(python3 -c "import json,sys; print(json.load(open('/tmp/w/e'))['err'])" 2>/dev/null || cat /tmp/w/e)
    printf '%s\n    => ERROR: %s\n' "$line" "$err"
  else
    printf '%s\n    => [%s]\n' "$line" "$out"
  fi
done
SH
chmod +x /tmp/w/run.sh
/tmp/w/run.sh <<'EOF'
{{ strings.ToUpper "hello, world!" }}
{{ strings.ToUpper "" }}
{{ strings.ToUpper 123 }}
{{ strings.ToUpper true }}
{{ strings.ToUpper 1.5 }}
{{ strings.ToUpper nil }}
{{ strings.ToUpper (coll.Slice 1 2) }}
{{ strings.ToUpper "ünïcödé ß ﬁ" }}
{{ strings.ToUpper "istanbul ı i" }}
{{ toUpper "abc" }}
{{ "abc" | strings.ToUpper }}
{{ strings.ToUpper (dict "a" 1) }}
EOF

