def abbrev(s, offset, maxWidth):
    if s == "": return ("", None)
    if maxWidth < 4: return (None, "width4")
    if len(s) <= maxWidth: return (s, None)
    if offset > len(s): offset = len(s)
    if len(s) - offset < (maxWidth - 3):
        offset = len(s) - (maxWidth - 3)
    m = "..."
    if offset <= 4:
        return (s[0:maxWidth-3] + m, None)
    if maxWidth < 7: return (None, "width7")
    if (offset + maxWidth - 3) < len(s):
        r, e = abbrev(s[offset:], 0, maxWidth-3)
        if e: return (None, e)
        return (m + r, None)
    return (m + s[len(s)-(maxWidth-3):], None)
PY
