import subprocess, json
def g(tmpl):
    p=subprocess.run(['/workspace/executable','-i','<'+tmpl+'>'],capture_output=True,text=True,cwd='/workspace')
    if p.returncode!=0:
        try: return ('ERR', json.loads(p.stderr)['err'])
        except Exception: return ('ERR', p.stderr.strip())
    o=p.stdout
    assert o.startswith('<') and o.endswith('>'), repr(o)
    return o[1:-1]
def ww(width, s, lb=None):
    if lb is None: t='{{ strings.WordWrap %d %s }}'%(width,json.dumps(s))
    else: t='{{ strings.WordWrap %d %s %s }}'%(width,json.dumps(lb),json.dumps(s))
    return g(t)
